#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=1L)stop("Provide project.yaml",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");`%||%`<-function(x,y)if(is.null(x)||!length(x))y else x;nonempty_file<-function(path)length(path)&&nzchar(path)&&file.exists(path)&&file.info(path)$size>0
source(file.path(root,"app/shiny/R/project_discovery.R"));source(file.path(root,"app/shiny/R/fitness_design_state.R"));project<-read_project_summary(args[[1]],root);design<-read_fitness_design(project);ids<-fitness_default_selection(design);all4<-resolve_selected_fitness_comparisons(design,ids);yh298<-resolve_selected_fitness_comparisons(design,grep("yH298",ids,value=TRUE));unknown<-resolve_selected_fitness_comparisons(design,c(ids,"not_a_comparison"));reversed<-resolve_selected_fitness_comparisons(design,rev(ids));optional<-resolve_selected_fitness_comparisons(design[c("comparison_id","parent_sample","treated_sample")],ids);missing<-resolve_selected_fitness_comparisons(design[c("comparison_id","treated_sample")],ids)
stopifnot(length(ids)==4L,nrow(all4$rows)==4L,nrow(yh298$rows)==2L,identical(unknown$unknown_ids,"not_a_comparison"),identical(all4$selected_ids,reversed$selected_ids),!any(ids%in%names(all4$rows)),nrow(optional$rows)==4L,!missing$valid,grepl("parent_sample",missing$message,fixed=TRUE));cat("PASS\n")
